/* FarhangGram — original book-teacher raster mascot, preview variant.
   SVG is only a sizing/cropping wrapper around the original WebP artwork.
   No simplified/vector-redrawn character is used. No network dependency. */
(function () {
  'use strict';
  var IMAGES = {"normal":"data:image/webp;base64,","happy":"data:image/webp;base64,","think":"data:image/webp;base64,","oops":"data:image/webp;base64,","cheer":"data:image/webp;base64,"};
  var STATES = { normal: {}, happy: {}, think: {}, cheer: {}, oops: {} };
  function known(state) { return Object.prototype.hasOwnProperty.call(IMAGES, state) ? state : 'normal'; }
  function imageData(state) { return IMAGES[known(state)]; }
  function mascotLabel(state) {
    switch (known(state)) {
      case 'happy': return 'کتاب همراه، خوشحال';
      case 'cheer': return 'کتاب همراه در حال جشن';
      case 'think': return 'کتاب همراه در حال فکر';
      case 'oops': return 'کتاب همراه: دوباره امتحان کنیم';
      default: return 'کتاب همراه، دستیار تو';
    }
  }
  function svg(state, size) {
    state = known(state);
    var s = Math.max(1, Math.min(1024, Number(size) || 64));
    /* Full original artwork at every size: never crop hands, feet or gestures. */
    var view = '0 0 512 512';
    return '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" class="mascot m-' + state +
      ' book-mascot book-mascot-full' + '" width="' + s + '" height="' + s +
      '" viewBox="' + view + '" preserveAspectRatio="xMidYMid meet" role="img" aria-label="' + mascotLabel(state) + '">' +
      '<image class="book-mascot-art" x="0" y="0" width="512" height="512" xlink:href="' + IMAGES[state] + '"/>' +
      '</svg>';
  }
  function svgStandalone(state, size) { return svg(state, size); }
  function confetti(container, count) {
    if (!container) return;
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    var n = Math.min(30, count || 22);
    var frag = document.createDocumentFragment();
    for (var i = 0; i < n; i++) {
      var p = document.createElement('i');
      p.className = 'confetti-bit';
      p.style.setProperty('--x', (Math.random() * 100).toFixed(1) + '%');
      p.style.setProperty('--d', (Math.random() * 0.5).toFixed(2) + 's');
      p.style.setProperty('--r', Math.round(Math.random() * 360) + 'deg');
      p.style.setProperty('--c', ['#10B981', '#F59E0B', '#60A5FA', '#F472B6'][i % 4]);
      frag.appendChild(p);
    }
    container.appendChild(frag);
    setTimeout(function () {
      if (container && container.parentNode) {
        var bits = container.querySelectorAll('.confetti-bit');
        for (var k = 0; k < bits.length; k++) {
          if (bits[k].parentNode) bits[k].parentNode.removeChild(bits[k]);
        }
      }
    }, 1600);
  }


  function resultState(correct, total) {
    var n = Number(total), c = Number(correct);
    if (!(n > 0) || !isFinite(c)) return 'normal';
    var ratio = Math.max(0, Math.min(1, c / n));
    return ratio >= 0.85 ? 'cheer' : (ratio >= 0.5 ? 'happy' : 'think');
  }
  function scenarioState(scenario) {
    return { welcome: 'normal', guide: 'think', question: 'think', correct: 'happy',
      incorrect: 'oops', retry: 'think', achievement: 'cheer' }[scenario] || 'normal';
  }
  window.FGMascot = { svg: svg, svgStandalone: svgStandalone, imageData: imageData,
    confetti: confetti, label: mascotLabel, STATES: STATES, renderer: 'original-webp-full', resultState: resultState, scenarioState: scenarioState };
})();
